-- SQLite has no AUTO_INCREMENT on non-primary-key columns. These columns were AUTO_INCREMENT in MySQL and are
-- shown to people (order numbers, SKUs, PO numbers), so they are filled after insert with MAX + 1.
-- SQLite runs one write at a time, so two inserts can never take the same number; the UNIQUE index keeps MAX O(log n).
CREATE TRIGGER IF NOT EXISTS trg_discount_auto_id AFTER INSERT ON "discount"
WHEN NEW."auto_id" IS NULL
BEGIN
  UPDATE "discount" SET "auto_id" = (SELECT COALESCE(MAX("auto_id"), 0) + 1 FROM "discount") WHERE rowid = NEW.rowid;
END;

CREATE TRIGGER IF NOT EXISTS trg_product_variant_sku AFTER INSERT ON "product_variant"
WHEN NEW."sku" IS NULL
BEGIN
  UPDATE "product_variant" SET "sku" = (SELECT COALESCE(MAX("sku"), 0) + 1 FROM "product_variant") WHERE rowid = NEW.rowid;
END;

