-- Full-text search on product titles (MySQL FULLTEXT product_title_fulltext). External-content FTS5 table, kept
-- in sync by triggers, so product search is an index lookup instead of a LIKE scan.
CREATE VIRTUAL TABLE IF NOT EXISTS product_fts USING fts5(title, content='product', content_rowid='rowid', tokenize='unicode61 remove_diacritics 2');

CREATE TRIGGER IF NOT EXISTS trg_product_fts_ai AFTER INSERT ON "product" BEGIN
  INSERT INTO product_fts(rowid, title) VALUES (NEW.rowid, NEW.title);
END;
CREATE TRIGGER IF NOT EXISTS trg_product_fts_ad AFTER DELETE ON "product" BEGIN
  INSERT INTO product_fts(product_fts, rowid, title) VALUES ('delete', OLD.rowid, OLD.title);
END;
CREATE TRIGGER IF NOT EXISTS trg_product_fts_au AFTER UPDATE OF "title" ON "product" BEGIN
  INSERT INTO product_fts(product_fts, rowid, title) VALUES ('delete', OLD.rowid, OLD.title);
  INSERT INTO product_fts(rowid, title) VALUES (NEW.rowid, NEW.title);
END;

-- 1) product_warehouse_visibility: the code upserts on (warehouse_id, product_id, product_variant_id), but MySQL
--    had no unique key there, so ON DUPLICATE KEY never matched and every save appended a duplicate row.
--    Keep the most recently updated row of any duplicate group, then enforce uniqueness.
DELETE FROM "product_warehouse_visibility"
WHERE "rowid" NOT IN (
  SELECT "rowid" FROM (
    SELECT "rowid", ROW_NUMBER() OVER (
      PARTITION BY "warehouse_id", "product_id", "product_variant_id" ORDER BY "updated_at" DESC, "rowid" DESC
    ) AS rn FROM "product_warehouse_visibility"
  ) WHERE rn = 1
);
CREATE UNIQUE INDEX IF NOT EXISTS "uq_pwv_warehouse_product_variant"
  ON "product_warehouse_visibility"("warehouse_id", "product_id", "product_variant_id");

-- 2) MySQL trigger trg_update_showtime_status: seat confirmations move showtime.available_seats and the
--    selling / sold_out status.
CREATE TRIGGER IF NOT EXISTS "trg_update_showtime_status"
AFTER UPDATE OF "reservation_status" ON "seat_reservation"
BEGIN
  UPDATE "showtime" SET "available_seats" = "available_seats" - 1
  WHERE "showtime_id" = NEW."showtime_id" AND OLD."reservation_status" = 'pending' AND NEW."reservation_status" = 'confirmed';

  UPDATE "showtime" SET "available_seats" = "available_seats" + 1
  WHERE "showtime_id" = NEW."showtime_id" AND OLD."reservation_status" = 'confirmed' AND NEW."reservation_status" = 'pending';

  UPDATE "showtime" SET "status" = CASE
      WHEN "available_seats" = 0 AND "status" IN ('scheduled', 'selling') THEN 'sold_out'
      WHEN "available_seats" > 0 AND "status" IN ('scheduled', 'sold_out') THEN 'selling'
      ELSE "status" END
  WHERE "showtime_id" = NEW."showtime_id";
END;
-- The MySQL EVENT ev_update_showtime_status (started / ended every 10 min) is the cron job
-- GET /api/cron/showtime-status (see apps/api/src/cron/showtime-status.ts).

-- Table + Tag ordering, table change history and kitchen "table changed" tickets.
ALTER TABLE "customer_order" ADD COLUMN "tag_no" TEXT;
CREATE UNIQUE INDEX "uq_open_tag" ON "customer_order"("warehouse_id", "tag_no")
  WHERE "order_status" = 'DRAFT' AND "tag_no" IS NOT NULL AND "tag_no" <> '';

CREATE TABLE "table_change_log" (
  "id" TEXT NOT NULL PRIMARY KEY,
  "request_id" TEXT NOT NULL,
  "warehouse_id" TEXT NOT NULL,
  "order_id" TEXT NOT NULL,
  "invoice_no" INTEGER,
  "tag_no" TEXT,
  "from_table_id" TEXT NOT NULL,
  "from_table_name" TEXT NOT NULL,
  "to_table_id" TEXT NOT NULL,
  "to_table_name" TEXT NOT NULL,
  "changed_by" TEXT NOT NULL,
  "changed_by_name" TEXT NOT NULL,
  "changed_at" TEXT NOT NULL,
  "reason" TEXT
);
CREATE UNIQUE INDEX "uq_table_change_request" ON "table_change_log"("request_id");
CREATE INDEX "ix_table_change_order" ON "table_change_log"("order_id", "changed_at");

ALTER TABLE "print_queue" ADD COLUMN "kind" TEXT NOT NULL DEFAULT 'NEW_ORDER';
ALTER TABLE "print_kitchen_log" ADD COLUMN "kind" TEXT NOT NULL DEFAULT 'NEW_ORDER';
